import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"3、【屯】 震下坎上","description":"周易口訣義 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"周易口訣義 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"classics/koujueyi/005.md","filePath":"classics/koujueyi/005.md"}'),r={name:"classics/koujueyi/005.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><p>彖曰：屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。</p><p>象曰：雲雷，屯，君子以經綸。</p><p>初九：磐桓，利居貞，利建侯。</p><p>象曰：雖「盤桓」，志行正也。以貴下賤，大得民也。</p><p>六二：屯如邅如，乘馬班如，匪寇婚媾。女子貞不字，十年乃字。</p><p>象曰：六二之難，乘剛也。「十年乃字」，反常也。</p><p>六三，即鹿無虞，惟入於林中，君子幾不如舍，往吝。</p><p>象曰：「即鹿無虞」，以從禽也。君子舍之，「往吝」窮也。</p><p>六四，乘馬班如，求婚媾，往吉，無不利。</p><p>象曰：求而往，明也。</p><p>九五，屯其膏，小貞吉，大貞兇。</p><p>象曰：「屯其膏」，施未光也。</p><p>上六，乘馬班如，泣血漣如。</p><p>象曰：「泣血漣如」，何可長也！</p><p>解讀</p><p>「屯元亨利貞」者，屯，難也，盈也，天地造始，剛柔始交，動則難生，故曰「難」也。元，大也，以天地始交為難，由難始大通也，故曰「元亨」；因此大通而乃以行貞正，故曰「利貞」也。「勿用有攸往」者，攸，所也，當屯難之時，小人道長，君子道消，若有所往，即為小人侵害，故勿用有所往也。「利建侯」者，處屯難之時，弱求於強，民思其主之時，故利建君侯以為民主。詩云「百姓盈盈，匪君子而不寧」是也。</p><p>象曰「雲雷屯，君子以經綸」者，李氏雲：「雲，陰也；雷，陽也。」陰陽二氣相激薄而未通感，情不相得，故難生也。君子處屯難之時，不得安然無事，經營綸理，以輔屯難也。</p><p>初九，磐桓，利居貞，利建侯者，磐桓，是進退不安之貌也。初九以剛陽之德，處群陰之下，即是用謙為體，以貴下賤者也。時未可通，磐桓不安，但以守正而不失其居，故曰「利居貞」也。處難之時，以謙得眾，民思其君之時，故利封建君侯，以為民主也。</p><p>「六二，屯如邅如，乘馬班如，匪寇婚媾。女子貞不字，十年乃字」者，邅，回也；字，愛也。處屯難之時，強者陵弱，六二是九五之匹，時逢險難，與初相近，情不相得，被初為難，不獲前進，故邅回也。「乘馬班如」者，班旋不進貌也。二既去五既遠，但乘馬班旋而不敢前進。「女子貞不字」者，二是五之匹，故執貞奉五，而不受初之字愛也。十年反常，難道乃通，故受五之所愛矣。易之為書，曲暢義理，反明人事，所言「女子不字」，亦猶忠臣遇難，上下暌違，守節不違，其如蘇武困於單于，後乃歸漢也。</p><p>六三即鹿無虞，惟入於林中，君子幾不如舍？「往吝」者，即，就也；虞是掌山澤之官也。六三處屯難之時，陰先求陽，弱者求強，而六三既無正應，往依於五，五又有應在二，而六三若往就五，五所不納，猶如獵鹿，要假虞官，揆度山川，知鹿所在，既無虞人，徒入於林，終不獲鹿。故君子見此，不如棄捨，若強就之，徒勞而已，終至悔吝。故略例雲「見情者獲，直往即違」是也。</p><p>「六四乘馬班如，求婚媾，往吉，無不利」者，六四意就初九，見二與初相近，疑二與初相合，心懷嫌疑，故乘馬班旋而不敢進。今六二不從於初，而六四見其情狀，可以就往初九，必獲媾合，是以往獲吉而無不利，言兩情相得也。「九五屯其膏，小貞吉，大貞兇」者，九五既處尊位，當屯難之時，固宜拯弱救衰，濟民危難，而乃獨應於二，即是用心𥚹狹，所濟不廣，處難以斯，乃非大人弘博之道，即是「小貞吉，大貞兇」也。「膏」，喻恩澤施惠之義。</p><p>「上六：乘馬班如，泣血漣如」者，居陰柔之質而無應援，處難之時不能自濟，雖復乘馬之班旋而無所適，故泣血沲嗟，滅亡在近。說文雲：「漣如，泣垂下之貌也。」</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
